TITLES = {
    "lookups": ("Lookups", "Lookups", "Recherches", "Ricerche", "Lookups", "Búsquedas", "Pesquisas", "Opzoekingen", "Sorgulamalar"),
    "feeds": ("Feeds", "Feeds", "Flux", "Feed", "Feeds", "Feeds", "Feeds", "Feeds", "Akışlar"),
}
LOOKUP_NAMES = "nowplaying deezer itunes mcserver mcplayer roblox steam chess modrinth pokemon twitch kick youtube github npm pypi anime movie show wikipedia crypto convert bluesky mastodon reddit".split()


def PATCH(data, i):
    lang = LANGS[i]
    bot = json.loads((BOT / f"{lang}.json").read_text(encoding="utf-8"))
    clean = lambda s: s.replace("`", "")
    for item in data["landing"]["modulesDetail"]:
        if item.get("key") == "invite_tracking":
            item["desc"] = INVITE_DESC[i]
    groups = data["commands"]["groups"]
    invite = next(g for g in groups if g["key"] == "invite_tracking")
    if not any(c["name"] == "/statistics" for c in invite["commands"]):
        pos = next((n for n, c in enumerate(invite["commands"]) if c["name"] == "/inviteleaderboard"), len(invite["commands"]) - 1) + 1
        invite["commands"].insert(pos, {"name": "/statistics", "description": clean(bot["general.cmd_statistics"])})
    new = {
        "lookups": [{"name": f"/lookup {c}", "description": clean(bot[f"general.cmd_lookup_{c}"])} for c in LOOKUP_NAMES],
        "feeds": [{"name": f"/feed {c}", "description": clean(bot[f"general.cmd_feed_{c}"])} for c in ("add", "list", "sources")],
    }
    for key in ("feeds", "lookups"):
        entry = {"key": key, "title": TITLES[key][i], "premium": False, "commands": new[key]}
        at = next((n for n, g in enumerate(groups) if g["key"] == key), None)
        if at is not None:
            groups[at] = entry
        else:
            after = next(n for n, g in enumerate(groups) if g["key"] == "invite_tracking")
            groups.insert(after + 1, entry)
